import type { IncomingMessage, ServerResponse } from "node:http";
// Generated by the production build before Vercel packages the function.
// @ts-expect-error Generated build artifact is absent during the standalone TypeScript check.
import { createApp } from "../dist/app.js";

type VercelRequest = IncomingMessage & { method?: string; url?: string };
type VercelResponse = ServerResponse & {
  status?: (code: number) => VercelResponse;
  json?: (body: unknown) => void;
};

const app = createApp();

export default function handler(req: VercelRequest, res: VercelResponse) {
  return (app as unknown as (request: VercelRequest, response: VercelResponse) => unknown)(req, res);
}
